\label{def:protocol}



A {\bf NOF protocol} $P$ consists of maps
\begin{align}
  \mathrm{strat} : & [d] \to G^{d - 1} \to \mathrm{List} \mathrm{Bool} \to \mathrm{Bool} \\
  \mathrm{guess} : & [d] \to G^{d - 1} \to \mathrm{List} \mathrm{Bool} \to \mathrm{Bool}
\end{align}

\begin{align}
    \mathrm{strat} : & [d] \to G^{d - 1} \to \mathrm{List} \mathrm{Bool} \to \mathrm{Bool} \\
    \mathrm{guess} : & [d] \to G^{d - 1} \to \mathrm{List} \mathrm{Bool} \to \mathrm{Bool}
  \end{align}

\label{def:broadcast}




Given a NOF protocol $P$, the {\bf NOF broadcast on input $x : G^d$} is inductively defined by
\begin{align}
  \mathrm{broad}(x) : \mathbb{N} & \to \mathrm{List} \mathrm{Bool} \\
  0 & \mapsto [] \\
  t + 1 & \mapsto \mathrm{strat}_{t \% d}(\mathrm{forget}_{t \% d}(x), \mathrm{broad}(x, t)) :: \mathrm{broad}(x, t)
\end{align}

\begin{align}
    \mathrm{broad}(x) : \mathbb{N} & \to \mathrm{List} \mathrm{Bool} \\
    0 & \mapsto [] \\
    t + 1 & \mapsto \mathrm{strat}_{t \% d}(\mathrm{forget}_{t \% d}(x), \mathrm{broad}(x, t)) :: \mathrm{broad}(x, t)
  \end{align}

\label{def:eval}



The {\bf $\mathrm{eval}$ function} is defined by
\begin{align}
    \mathrm{eval} : G^d & \to \mathrm{Bool} \\
    x & \mapsto \begin{cases}
    1 & \text{ if } \sum_i x_i = 0 \\
    0 & \text{ else}
  \end{cases}
\end{align}

